```js
// In-memory note store
const notes = new Map();
let counter = 0;

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The title of the note.' },
          body: { type: 'string', description: 'The body of the note.' },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
    {
      name: 'note_get',
      description: 'Get a note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' },
        },
        required: ['note_id'],
        additionalProperties: false,
      },
    },
  ];
}

function requireString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`Invalid argument: ${name} must be a non-empty string`);
  }
}

export async function callTool(name, args) {
  args = args || {};
  if (name === 'note_create') {
    const { title, body } = args;
    requireString(title, 'title');
    requireString(body, 'body');
    const id = 'n' + (++counter);
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id}: ${title}` }],
    };
  }
  if (name === 'note_get') {
    const { note_id } = args;
    requireString(note_id, 'note_id');
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Note not found: ${note_id}`);
    }
    return {
      content: [{ type: 'text', text: `${note.title}\n\n${note.body}` }],
    };
  }
  throw new Error(`Unknown tool: ${name}`);
}
```

This looks good. Let me verify:
- `note_create` with `{title:'A',body:'B'}` returns content[0].text = `Created note n1: A`. The regex `/n\d+/` matches `n1`. 
- `note_get` with `{note_id:'n1'}` returns content[0].text = `A\n\nB`. The regex `/A/` matches `A`. 

The id is stable and generated (incrementing counter). For multiple notes they'd be n1, n2, etc.

